#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "Deep Research — infrastructure setup"

# ── Stage 1: Postgres + Redis ────────────────────────────────────────────
stage "Postgres + Redis: connection strings"
say "We need a Postgres 16+ and Redis 7+ reachable from this machine."
say "If you already have them running elsewhere, paste the connection string."
say "If not, the easiest path is two docker-run lines."
say ""
note "Quick start (copy-paste these into another terminal if you like):"
say "  docker run -d --name dr-postgres -p 5432:5432 -e POSTGRES_USER=postgres -e POSTGRES_PASSWORD=postgres -e POSTGRES_DB=deep_research postgres:16"
say "  docker run -d --name dr-redis -p 6379:6379 redis:7-alpine"
step "Open a terminal and run the docker commands above (or use your own Postgres/Redis)."
step "Then come back and paste the connection strings."
ask DATABASE_URL "Paste DATABASE_URL  (e.g. postgresql+asyncpg://postgres:postgres@localhost:5432/deep_research):"
ask REDIS_URL "Paste REDIS_URL  (e.g. redis://localhost:6379/0):"
ask MILVUS_URI "Paste MILVUS_URI  (optional for v1; can leave blank):"
write_env DATABASE_URL "$DATABASE_URL"
write_env REDIS_URL "$REDIS_URL"
[[ -n "$MILVUS_URI" ]] && write_env MILVUS_URI "$MILVUS_URI"

# ── Stage 2: Langfuse ─────────────────────────────────────────────────────
stage "Langfuse: host + API keys"
say "Langfuse is our observability + prompt-management layer."
say "Two paths:"
say "  • Easiest: Langfuse Cloud (free tier) at https://cloud.langfuse.com"
say "  • Self-host: docker run -p 3000:3000 langfuse/langfuse"
say "We'll use whatever you already have. Cloud is recommended for getting started."
open_url "https://cloud.langfuse.com"
step "Sign up / sign in."
step "Create a new project (or pick existing)."
step "Go to ⚙ Settings → API Keys."
step "Create a new secret key. Copy the Public Key and Secret Key values."
ask LANGFUSE_HOST "Paste LANGFUSE_HOST  (Cloud: https://cloud.langfuse.com  OR your self-host URL):"
ask LANGFUSE_PUBLIC_KEY "Paste LANGFUSE_PUBLIC_KEY  (starts with pk-lf-):"
ask_secret LANGFUSE_SECRET_KEY "Paste LANGFUSE_SECRET_KEY  (starts with sk-lf-):"
write_env LANGFUSE_HOST "$LANGFUSE_HOST"
write_env LANGFUSE_PUBLIC_KEY "$LANGFUSE_PUBLIC_KEY"
write_env LANGFUSE_SECRET_KEY "$LANGFUSE_SECRET_KEY"

# ── Stage 3: Anthropic API key ───────────────────────────────────────────
stage "Anthropic: API key"
say "We use Anthropic Claude for the main research pipeline."
open_url "https://console.anthropic.com/settings/keys"
step "Sign in, then Settings → API Keys."
step "Create Key. Give it a name like 'deep-research-dev'. Copy the key (starts sk-ant-)."
ask_secret ANTHROPIC_API_KEY "Paste ANTHROPIC_API_KEY:"
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"

# ── Stage 4: Tavily API key ──────────────────────────────────────────────
stage "Tavily: API key"
say "Tavily is our default web search backend."
open_url "https://app.tavily.com/home"
step "Sign in (free tier OK; 1000 requests/month)."
step "API Keys (left nav) → Copy your default key (starts tvly-)."
ask_secret TAVILY_API_KEY "Paste TAVILY_API_KEY:"
write_env TAVILY_API_KEY "$TAVILY_API_KEY"

# ── Stage 5: OpenAI key (optional) ───────────────────────────────────────
stage "OpenAI: API key (optional)"
say "Only needed if you want to A/B test against GPT models (Phase 7)."
say "Skip this stage if you only plan to use Anthropic."
if confirm "Skip OpenAI?"; then
  note "Skipped — OpenAI key not required for v1 default flow."
else
  open_url "https://platform.openai.com/api-keys"
  step "Sign in, then Dashboard → API keys → Create new secret key."
  step "Copy the key (starts sk-)."
  ask_secret OPENAI_API_KEY "Paste OPENAI_API_KEY:"
  write_env OPENAI_API_KEY "$OPENAI_API_KEY"
fi

# ── Stage 6: 阿里云百炼 MCP (optional) ──────────────────────────────────
stage "阿里云百炼 Web Search MCP (optional)"
say "Only needed if you want to use 阿里云百炼 instead of Tavily as web search."
say "Switch via SEARCH_PROVIDER=bailian_mcp after setup."
if confirm "Skip Bailian MCP?"; then
  note "Skipped — Tavily will be the default search backend."
else
  open_url "https://bailian.console.aliyun.com/"
  step "Sign in / sign up. Go to 应用 → 我的应用 → 创建应用."
  step "开通 Web Search 能力. 复制 应用 ID 与 API Key."
  ask BAILIAN_MCP_URL "Paste BAILIAN_MCP_URL  (your MCP endpoint):"
  ask_secret BAILIAN_MCP_TOKEN "Paste BAILIAN_MCP_TOKEN:"
  write_env BAILIAN_MCP_URL "$BAILIAN_MCP_URL"
  write_env BAILIAN_MCP_TOKEN "$BAILIAN_MCP_TOKEN"
fi

# ── Stage 7: JWT_SECRET + finalize ────────────────────────────────────────
stage "JWT_SECRET + write .env + verify"
say "JWT_SECRET is a random 32-byte hex used to sign auth tokens."
say "We'll generate one and write everything to .env, then verify the file."
JWT_SECRET=$(openssl rand -hex 32)
note "Generated JWT_SECRET (hidden; written to .env)."

# Defaults from .env.example that the user might want to override later
write_env JWT_SECRET "$JWT_SECRET"
write_env SEARCH_PROVIDER "tavily"

note "Verifying .env syntax with docker compose config..."
if docker compose config --quiet 2>&1 | head -1; then
  note "docker compose config: OK"
elif command -v python3 >/dev/null 2>&1; then
  python3 -c "
import os, re
required = ['DATABASE_URL','REDIS_URL','LANGFUSE_HOST','LANGFUSE_PUBLIC_KEY','LANGFUSE_SECRET_KEY','ANTHROPIC_API_KEY','TAVILY_API_KEY','JWT_SECRET']
missing = [k for k in required if not os.environ.get(k) and not os.path.exists('.env')]
# Actually read .env
missing = []
with open('.env') as f:
    for line in f:
        line = line.strip()
        if not line or line.startswith('#'): continue
        if '=' not in line: continue
        key = line.split('=',1)[0]
        if key in required:
            required.remove(key)
missing = required
print('Missing keys:', missing if missing else 'none')
"
fi

note ""
note "All done. Next:"
note "  1. cp .env.example .env (if not done) — your values are now in .env"
note "  2. Run 'docker compose up -d' to start backend + worker + frontend."
note "  3. Visit http://localhost:8000/readyz to verify infra connectivity."
note "  4. Pick the next unblocked ticket from GitHub Issues and run /implement on it."

finish
